head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 radio의 label명과 label명의 위치를 확인한다.
    //1. After running the sample file, check the label name and label name of the radio.
    //Verify 1. clo2의 lable명은 '라벨위치'이고 radio버튼의 왼쪽에 명칭이 보여진다. col4의 lable명은 '라벨위치'이고 radio버튼의 오른쪽에 명칭이 보여진다.
    //1. The lable name of clo2 is 'label position' and the name is shown on the left of the radio button. The lable name of col4 is 'label position' and the name is shown on the right of the radio button.
    //col2
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').innerText == '라벨위치'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').children().first()[0].nodeName == 'LABEL'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').children().last()[0].nodeName == 'INPUT'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___radio_col2_0').attr('type') == 'radio'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //col4
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_3').innerText == '라벨위치'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_3').children().first()[0].nodeName == 'INPUT'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___radio_col4_0').attr('type') == 'radio'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_3').children().last()[0].nodeName == 'LABEL'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018           
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
